uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float dustType;
uniform float windMode;
uniform float blendMode;
uniform float autop;
uniform float autoSpeed;
uniform float progress;
uniform float scale;
uniform float angle;
uniform float2 position;
uniform float2 stretch;
uniform float alpha;
uniform float alphaComp;
uniform float layers;
uniform float density;
uniform float spacing;
uniform float size;
uniform float sizeVar;
uniform float opacity;
uniform float flicker;
layout(color) uniform half4 colA;
layout(color) uniform half4 colB;
uniform float colVar;
uniform float windAngle;
uniform float windSpeed;
uniform float gust;
uniform float gustSpeed;
uniform float swirlSpeed;
uniform float turb;
uniform float turbScale;
uniform float turbSpeed;
uniform float lift;
uniform float depthRange;
uniform float focus;
uniform float dof;
uniform float farFade;
uniform float mblur;
uniform float overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p) {
        float z = max(scale * 2.0, 0.002);
        p -= position;
        p = nmRot(p, -radians(angle));
        return p / (z * max(stretch, float2(0.01)));
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx, 0.0, 1.0) * clamp(alpha, 0.0, 1.0);
        float4 b = tex * clamp(alphaComp, 0.0, 1.0);
        float4 o;
        if (int(blendMode) == 0) o = f;
        else if (int(blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float4 h4(float2 c, float k) {
        float4 p = float4(dot(c, float2(127.1, 311.7)), dot(c, float2(269.5, 183.3)), dot(c, float2(419.2, 371.9)), dot(c, float2(91.7, 57.3))) + k * float4(13.7, 7.3, 3.1, 17.9);
        return fract(sin(p) * 43758.5453);
    }
    float segDist(float2 p, float2 a, float2 b) {
        float2 ab = b - a;
        float t = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-6), 0.0, 1.0);
        return length(p - a - ab * t);
    }
    float windDist(float t) {
        float g = clamp(gust, 0.0, 0.95), f = max(gustSpeed, 0.01);
        if (int(windMode) == 1) return t + g * sin(6.2831853 * f * t) / (6.2831853 * f) + g * 0.5 * sin(6.2831853 * f * 0.37 * t + 1.7) / (6.2831853 * f * 0.37);
        if (int(windMode) == 3) { float ph = t * f; return (1.0 - g) * t + g / f * (floor(ph) + smoothstep(0.0, 0.35, fract(ph))); }
        return t;
    }
    float windRate(float t) {
        float g = clamp(gust, 0.0, 0.95), f = max(gustSpeed, 0.01);
        if (int(windMode) == 1) return 1.0 + g * cos(6.2831853 * f * t) + g * 0.5 * cos(6.2831853 * f * 0.37 * t + 1.7);
        if (int(windMode) == 3) { float u = fract(t * f) / 0.35; return (1.0 - g) + g * (u < 1.0 ? 6.0 * u * (1.0 - u) / 0.35 : 0.0); }
        return 1.0;
    }
    void amzRender() {
        float4 lay = amzTexture(0, amzScreenNorm());
        float2 L = layer;
        float2 p = (amzLayerNorm() - 0.5) * L;
        p = nmStd(float2(p.x, -p.y));
        float T = progress * 10.0 + ((autop>0.5) ? time * autoSpeed : 0.0);
        float wa = radians(windAngle);
        float2 wdir = float2(cos(wa), -sin(wa));
        float wd = windSpeed * windDist(T);
        float wr = windSpeed * windRate(T);
        float N = clamp(floor(layers + 0.5), 1.0, 16.0);
        float cs = max(spacing, 2.0);
        float4 acc = float4(0.0);
        for (int li = 0; li < 16; li++) {
            float i = float(li);
            if (i >= N) break;
            float zn = (i + 0.5) / N;
            float z = mix(1.0, max(depthRange, 1.0), zn);
            float k = 1.0 / z;
            float2 pw = p / k;
            if (int(windMode) == 2) {
                float r = length(pw);
                pw = nmRot(pw, -radians(swirlSpeed * T) * (1.0 + 600.0 / (r * k + 200.0)) * k);
            }
            float2 shift = wdir * wd + float2(0.0, -lift * T);
            float2 q = pw - shift + float2(i * 913.7, i * 517.3);
            float2 cell = floor(q / cs);
            float blurPx = dof * abs(zn - focus) * 14.0;
            float fl = 1.0 - farFade * zn * zn;
            float2 vel = (wdir * wr + float2(0.0, -lift)) * k;
            for (int oy = -1; oy <= 1; oy++) {
                for (int ox = -1; ox <= 1; ox++) {
                    float2 cid = cell + float2(float(ox), float(oy));
                    float4 h = h4(cid, i);
                    if (h.x > density) continue;
                    float2 base = (cid + 0.15 + 0.7 * h.yz) * cs;
                    float2 wpos = base + shift;
                    float tt = T * turbSpeed + h.w * 6.2831853;
                    float2 tdisp = turb * float2(sin(wpos.y / turbScale + tt) + 0.5 * sin(wpos.x / (turbScale * 0.6) - tt * 1.3),
                                             cos(wpos.x / turbScale * 1.1 - tt * 0.9) + 0.5 * cos(wpos.y / (turbScale * 0.7) + tt * 1.7));
                    float2 d = (q - base - tdisp) * k;
                    float sz = max(size * (1.0 - sizeVar + sizeVar * 2.0 * h.y) * mix(0.55, 1.0, k) * (int(dustType) == 3 ? 2.2 : 1.0), 0.25);
                    float rad = sz + blurPx * (int(dustType) == 3 ? 2.0 : 1.0);
                    float energy = sz / rad;
                    float dist;
                    float a;
                    float2 vstreak = vel * mblur * (int(dustType) == 1 ? 0.22 : 0.04);
                    if (int(dustType) == 2) {
                        float ang = h.w * 6.2831853 + T * (1.0 + 2.0 * h.z);
                        float2 dr = nmRot(d, -ang);
                        float flip = 0.25 + 0.75 * abs(cos(T * (1.5 + h.y * 2.0) + h.x * 9.0));
                        dr.y /= flip;
                        dr.x /= 1.0 + 0.6 * h.z;
                        dist = length(dr);
                        a = exp(-pow(dist / (rad * 1.3), 2.0) * 1.5) * (0.5 + 0.5 * flip);
                    } else if (int(dustType) == 3) {
                        dist = length(d);
                        float disc = 1.0 - smoothstep(rad * 0.85, rad, dist);
                        float rim = exp(-pow((dist - rad * 0.9) / max(rad * 0.08, 0.5), 2.0)) * 0.35;
                        a = (disc * 0.65 + rim) * (blurPx > 0.5 ? 1.0 : 0.0) + exp(-pow(dist / max(sz, 0.5), 2.0) * 2.0) * (blurPx > 0.5 ? 0.0 : 1.0);
                    } else {
                        dist = segDist(d, -vstreak * 0.5, vstreak * 0.5);
                        a = exp(-pow(dist / rad, 2.0) * 2.0);
                        float sl = length(vstreak);
                        a *= rad / (rad + sl * 0.5);
                        if (int(dustType) == 4) a += 0.12 * exp(-dist / (rad * 2.0));
                    }
                    float tw = 1.0 - flicker * (0.5 + 0.5 * sin(T * (3.0 + 5.0 * h.z) + h.w * 40.0));
                    float v = a * energy * fl * tw * opacity;
                    if (v < 0.002) continue;
                    float3 col = mix(colA.rgb, colB.rgb, h.z * colVar);
                    if (int(dustType) == 4) col = mix(float3(1.0, 0.85, 0.5), float3(1.0, 0.35, 0.05), h.z) * (1.0 + 0.6 * (1.0 - smoothstep(0.0, rad, dist)));
                    acc.rgb += col * v;
                    acc.a += v;
                }
            }
        }
        acc.a = clamp(acc.a, 0.0, 1.0);
        acc.rgb = min(acc.rgb, float3(1.0));
        acc.rgb = min(acc.rgb, float3(max(acc.a, 1e-4)) * 1.5);
        amzOutput = nmBlend(lay, acc);
        if (!(overdrawOn>0.5)) amzOutput *= lay.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
